q_k = \begin{cases}
                 \omega^2 \quad & k<m \text{ odd},
                 \\ \omega & k<m \text{ even}
             \end{cases} \qquad \text{and} \qquad q_m = \begin{cases}
                 \omega \quad & m \text{ odd},
                 \\ \omega^2 & m \text{ even}.
             \end{cases}
